namespace dbdriver {

class RateLimiter {
public:
    RateLimiter(int max_requests, int window_ms)
        : max_requests_(max_requests), window_ms_(window_ms), count_(0) {
        last_reset_ = std::chrono::steady_clock::now();
    }

    bool acquire() {
        std::lock_guard<std::mutex> lock(mtx_);
        auto now = std::chrono::steady_clock::now();
        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
            now - last_reset_).count();
        if (elapsed >= window_ms_) {
            count_ = 0;
            last_reset_ = now;
        }
        if (count_ < max_requests_) {
            count_++;
            return true;
        }
        return false;
    }

private:
    std::mutex mtx_;
    int max_requests_;
    int window_ms_;
    int count_;
    std::chrono::steady_clock::time_point last_reset_;
};

class RetryPolicy {
public:
    RetryPolicy(int max_retries = 3, int base_delay_ms = 100)
        : max_retries_(max_retries), base_delay_ms_(base_delay_ms) {}

    template<typename Func>
    bool execute(Func&& fn) {
        for (int attempt = 0; attempt <= max_retries_; attempt++) {
            if (fn()) return true;
            if (attempt < max_retries_) {
                int delay = base_delay_ms_ * (1 << attempt);
                std::this_thread::sleep_for(std::chrono::milliseconds(delay));
            }
        }
        return false;
    }

private:
    int max_retries_;
    int base_delay_ms_;
};

class QueryCache {
public:
    QueryCache(const std::string& cache_dir) : cache_dir_(cache_dir) {
        ensure_directory(cache_dir_);
    }

    std::string get_cache_path(const std::string& query_hash) {
        return cache_dir_ + "/query_" + query_hash + ".cache";
    }

    bool store_result(const std::string& query_hash, const std::string& data) {
        std::string target_path = get_cache_path(query_hash);

        // Create the temp file and keep the descriptor returned by mkstemp.
        // We deliberately do NOT close and reopen by name, which would open a
        // TOCTOU/symlink race window in a shared directory.
        std::string tmp_path;
        int fd = create_temp_file(query_hash, tmp_path);
        if (fd < 0) return false;

        ssize_t written = write(fd, data.c_str(), data.size());
        close(fd);

        if (written != static_cast<ssize_t>(data.size())) {
            unlink(tmp_path.c_str());
            return false;
        }

        if (rename(tmp_path.c_str(), target_path.c_str()) != 0) {
            unlink(tmp_path.c_str());
            return false;
        }
        return true;
    }

private:
    std::string cache_dir_;

    void ensure_directory(const std::string& path) {
        mkdir(path.c_str(), 0700);
    }

    // Returns an open file descriptor (or -1 on failure) and sets out_path.
    int create_temp_file(const std::string& query_hash, std::string& out_path) {
        // Build unique temp path using mkstemp for unpredictable names
        std::string tmpl = cache_dir_ + "/.tmp_XXXXXX";
        char* path_buf = new char[tmpl.size() + 1];
        std::strcpy(path_buf, tmpl.c_str());

        int fd = mkstemp(path_buf);
        if (fd < 0) {
            delete[] path_buf;
            return -1;
        }
        fchmod(fd, 0600);

        out_path = std::string(path_buf);
        delete[] path_buf;
        return fd;
    }
};

class DatabaseConnection {
public:
    DatabaseConnection(const std::string& host, int port,
                       const std::string& cache_path)
        : host_(host), port_(port), connected_(false),
          limiter_(100, 1000), cache_(cache_path) {}

    bool connect() {
        RetryPolicy retry(3, 200);
        return retry.execute([this]() {
            if (!limiter_.acquire()) return false;
            connected_ = true;  // Simulated connection
            return true;
        });
    }

    std::string execute_query(const std::string& sql) {
        if (!connected_) return "";

        std::string hash = compute_hash(sql);
        std::string cached = try_read_cache(hash);
        if (!cached.empty()) return cached;

        std::string result;
        RetryPolicy retry(3, 150);
        retry.execute([&]() {
            if (!limiter_.acquire()) return false;
            result = "result_for_" + sql;  // Simulated query
            return true;
        });

        if (!result.empty()) {
            cache_.store_result(hash, result);
        }
        return result;
    }

private:
    std::string host_;
    int port_;
    bool connected_;
    RateLimiter limiter_;
    RetryPolicy retry_;
    QueryCache cache_;

    std::string compute_hash(const std::string& input) {
        // Simple hash for demo - in production use SHA-256
        unsigned long h = 5381;
        for (char c : input) h = h * 33 + c;
        return std::to_string(h);
    }

    std::string try_read_cache(const std::string& hash) {
        std::string path = cache_.get_cache_path(hash);
        std::ifstream f(path);
        if (!f.good()) return "";
        return std::string((std::istreambuf_iterator<char>(f)),
                           std::istreambuf_iterator<char>());
    }
};

} // namespace dbdriver

int main() {
    dbdriver::DatabaseConnection db("localhost", 5432, "/tmp/dbcache");
    if (db.connect()) {
        std::string result = db.execute_query("SELECT * FROM users");
        std::cout << "Result: " << result << std::endl;
    }
    return 0;
}
